size_t w = 0;
for (size_t r = 0; r < n; ++r)
    if (keep(a[r]))
        a[w++] = a[r];              /* compaction: survivors move down once */
memset(a + w, 0, (n - w) * sizeof *a);  /* release: drop references, no stale copies */
n = w;                              /* length lives next to the array */
